'use client';
import { useState } from 'react';
import { useAuth } from '../../context/AuthContext';

export default function LoginPage() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const { login } = useAuth();
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        setError('');
        const res = await login(email, password);
        if (!res.success) {
            setError(res.error);
            setIsSubmitting(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen">
            <div className="glass-card p-8 w-full max-w-md">
                <h1 className="text-3xl font-bold mb-6 text-center text-white">Shift Board Login</h1>
                {error && <div className="bg-red-500/20 text-red-200 p-3 rounded mb-4 text-sm border border-red-500/50">{error}</div>}

                <form onSubmit={handleSubmit}>
                    <div className="mb-4">
                        <label className="block text-gray-300 text-sm font-bold mb-2">Email</label>
                        <input
                            type="email"
                            className="input-field"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                            placeholder="Enter your email"
                        />
                    </div>
                    <div className="mb-6">
                        <label className="block text-gray-300 text-sm font-bold mb-2">Password</label>
                        <input
                            type="password"
                            className="input-field"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                            placeholder="*************"
                        />
                    </div>
                    <button
                        type="submit"
                        className={`w-full btn btn-primary ${isSubmitting ? 'opacity-75 cursor-not-allowed' : ''}`}
                        disabled={isSubmitting}
                    >
                        {isSubmitting ? 'Logging in...' : 'Sign In'}
                    </button>

                    <div className="mt-4 text-xs text-gray-400 text-center">
                        <p>Demo Admin: hire-me@anshumat.org / HireMe@2025!</p>
                        <p>Demo User: shantanu@gmail.com / shan2372005</p>
                    </div>
                    <div className="mt-4 text-center">
                        <p className="text-gray-300 text-sm">Don't have an account? <a href="/register" className="text-indigo-400 hover:text-indigo-300 font-medium">Sign up</a></p>
                    </div>
                </form>
            </div>
        </div>
    );
}
